  "rounds": [
    {
      "id": "AI-01-1-A",
      "finding": "三项要求均满足。两个时段都显示对应试听间，选择可以更换。返回后仍勾选下午的南区试听间，直接提交和改选北区后提交的回执都与最终核对信息一致。",
      "anchor": "第1–2步显示两个时段及试听间，勾选从北区切换到南区。第3步核对为周三15:30–16:00南区，第4步返回后仍勾选该项，第5–6步核对与回执一致。第11步改选北区后，第12–13步均显示周三09:30–10:00北区。",
      "understand": {"score": 5, "basis": "“检查结果”逐项列出R1、R2、R3和附加路径，四项均为true。"},
      "locate": {"score": 5, "basis": "“走查记录”直接写出首次核对、返回勾选、提交前核对和回执的时段与试听间。"},
      "retrieve": {"score": 5, "basis": "从交付文件的“检查结果”即可取回三项判断和附加路径结论。"}
    },
    {
      "id": "AI-01-2-B",
      "finding": "两个时段都显示对应工坊，选择可以更换。问题发生在返回选择时，已核对的下午东侧工坊被重置为上午西侧工坊。重新选择东侧后，回执与最终核对信息一致。",
      "anchor": "第1–2步可见两个时段及工坊，并可切换勾选。第3步核对为周四16:00–16:30东侧工坊，第4步返回即勾选周四10:00–10:30西侧工坊，第10–11步再次出现同一问题。第5步重选东侧，第6–7步核对与回执一致。",
      "understand": {"score": 3, "basis": "需读到末尾“操作记录”，比较首次核对与返回后的勾选值，才能判断返回保留失败。"},
      "locate": {"score": 3, "basis": "末条日志记录了东侧变为西侧的操作和值，可据此定位到原始观察第3–4步。"},
      "retrieve": {"score": 3, "basis": "交付文件的v2日志保留了返回前后及提交前后的值，重读该条即可找回本轮核心判断。"}
    }
  ]
}
